/**
 * Asset module (Asset agent).
 *  - loadAssets(k): fetches public/assets/manifest.json, loads every sprite strip (sliceX = frames, anim "loop") and
 *    the bitmap font `sr_font`; tolerates missing files (registry simply lacks the key). Also binds the audio synth
 *    to KAPLAY's AudioContext.
 *  - createAudioService(save): runtime WebAudio chiptune + SFX synth (original, CC0).
 * Art is generated by `npm run art` (scripts/art/build.mjs). See docs/ASSET_MANIFEST.md.
 */
import type { KAPLAYCtx } from "kaplay";
import type { AudioService, SaveService, SpriteRegistry } from "../contracts";
import { loadSpritesAndFont } from "./loader";
import { bindAudioContext, createSynthAudio } from "./audio";

export async function loadAssets(k: KAPLAYCtx): Promise<SpriteRegistry> {
  try {
    bindAudioContext((k as unknown as { audioCtx?: AudioContext }).audioCtx);
  } catch {
    /* audio is optional */
  }
  try {
    const res = await loadSpritesAndFont(k);
    console.info(`[assets] ${res.loaded} sprites${res.fontLoaded ? " + font" : ""} loaded`);
    return res.registry;
  } catch (err) {
    console.warn("[assets] load failed, using fallbacks", err);
    return { has: () => false, info: () => undefined };
  }
}

export function createAudioService(save: SaveService): AudioService {
  return createSynthAudio(save);
}

export { assetUrl } from "./loader";
